<!--
  @component
  Converts markdown into html
  - @prop {string} `content` - Markdown content
  - @prop {boolean} `inline` - Whether to inline the content. 
-->

<script>
  import { markdown } from '@splendidlabz/utils'
  const { content, inline = false } = $props()
  const html = $derived(markdown(content, { inline }))
</script>

<!-- eslint-disable-next-line svelte/no-at-html-tags -->
{@html html}
